        MOD = 10 ** 9 + 7
        import sys
        sys.setrecursionlimit(5000)
        from functools import lru_cache

        @lru_cache(None)
        def f(i, j):
            if j == 0:
                return 1 if i == 0 else 0
            if i < j:
                return 0
            return (j * f(i - 1, j) + f(i - 1, j - 1)) % MOD

        return f(n, k)

