    int f(int i, int j) {
        if (j == 0) return i == 0 ? 1 : 0;
        if (i < j) return 0;
        if (memo[i][j] != -1) return memo[i][j];
        return memo[i][j] =
            (int)(((long long)j * f(i - 1, j) + f(i - 1, j - 1)) % MOD);
    }

